{"command": "mkdir -p /tmp/w && cd /tmp/w && cat > lap.c <<'EOF'
#include <stdlib.h>
#include <string.h>
/* Jonker-Volgenant dense LAP, minimization. x[i]=col of row i */
int lapjv(int n, const double *C, int *x){
  int *y=malloc(n*sizeof(int)), *freer=malloc(n*sizeof(int)), *col=malloc(n*sizeof(int)), *pred=malloc(n*sizeof(int)), *matches=calloc(n,sizeof(int));
  double *v=malloc(n*sizeof(double)), *d=malloc(n*sizeof(double));
  int i,j,k,numfree=0;
  /* column reduction */
  for(j=0;j<n;j++){y[j]=-1;}
  for(i=0;i<n;i++)x[i]=-1;
  for(j=n-1;j>=0;j--){
    double m=C[j]; int imin=0;
    for(i=1;i<n;i++){ if(C[(size_t)i*n+j]<m){m=C[(size_t)i*n+j];imin=i;} }
    v[j]=m;
    if(++matches[imin]==1){x[imin]=j;y[j]=imin;}
  }
  for(i=0;i<n;i++){
    if(matches[i]==0) freer[numfree++]=i;
    else if(matches[i]==1){
      int j1=x[i]; const double *r=C+(size_t)i*n; double m=1e300;
      for(j=0;j<n;j++) if(j!=j1){double h=r[j]-v[j]; if(h<m)m=h;}
      v[j1]-=m;
    }
  }
  /* augmenting row reduction, twice */
  for(int loop=0;loop<2;loop++){
    int k0=0, prv=numfree; numfree=0;
    while(k0<prv){
      i=freer[k0++];
      const double *r=C+(size_t)i*n;
      double u1=r[0]-v[0], u2=1e300; int j1=0,j2=-1;
      for(j=1;j<n;j++){double h=r[j]-v[j]; if(h<u2){ if(h>=u1){u2=h;j2=j;} else {u2=u1;u1=h;j2=j1;j1=j;} }}
      int i0=y[j1];
      if(u1<u2) v[j1]=v[j1]-(u2-u1);
      else if(i0>=0){ j1=j2; i0=y[j1]; }
      if(i0>=0){ if(u1<u2) freer[--k0]=i0; else freer[numfree++]=i0; }
      x[i]=j1; y[j1]=i;
    }
  }
  /* augmentation */
  for(int f=0;f<numfree;f++){
    int fr=freer[f], endofpath=-1, low=0, up=0, last=0;
    const double *r=C+(size_t)fr*n;
    for(j=0;j<n;j++){d[j]=r[j]-v[j]; pred[j]=fr; col[j]=j;}
    double mn=0;
    for(;;){
      if(up==low){
        last=low-1;
        mn=d[col[up++]];
        for(k=up;k<n;k++){ j=col[k]; double h=d[j];
          if(h<=mn){ if(h<mn){up=low; mn=h;} col[k]=col[up]; col[up++]=j; } }
        for(k=low;k<up;k++) if(y[col[k]]<0){ endofpath=col[k]; goto done; }
      }
      int j1=col[low++]; i=y[j1];
      const double *ri=C+(size_t)i*n;
      double u1=ri[j1]-v[j1]-mn;
      for(k=up;k<n;k++){ j=col[k]; double h=ri[j]-v[j]-u1;
        if(h<d[j]){ d[j]=h; pred[j]=i;
          if(h==mn){ if(y[j]<0){endofpath=j; goto done;} col[k]=col[up]; col[up++]=j; } } }
    }
  done:
    for(k=0;k<=last;k++){ j=col[k]; v[j]+=d[j]-mn; }
    for(;;){ i=pred[endofpath]; y[endofpath]=i; int t=x[i]; x[i]=endofpath; endofpath=t; if(i==fr)break; }
  }
  free(y);free(freer);free(col);free(pred);free(matches);free(v);free(d);
  return 0;
}
