{"command": "cat > sp.c <<'EOF'
#include <stdlib.h>
#include <string.h>
int lapjv(int n, const double *C, int *x);
#define INF 1e300
static int *adj, *deg, *y, *pred, *fin, *heap, *hpos, *scan;
static double *u, *v, *d;
static int cap_n = 0, *xx;
static void ensure(int n){
  if(cap_n>=n) return;
  if(cap_n){free(adj);free(deg);free(y);free(pred);free(fin);free(heap);free(hpos);free(scan);free(u);free(v);free(d);}
  cap_n=n; adj=malloc(sizeof(int)*(size_t)n*n); deg=malloc(sizeof(int)*n); y=malloc(sizeof(int)*n);
  pred=malloc(sizeof(int)*n); fin=malloc(sizeof(int)*n); heap=malloc(sizeof(int)*n); hpos=malloc(sizeof(int)*n);
  scan=malloc(sizeof(int)*n); u=malloc(sizeof(double)*n); v=malloc(sizeof(double)*n); d=malloc(sizeof(double)*n);
}
static int hn;
static void hup(int p){ int e=heap[p]; double k=d[e]; while(p>0){int q=(p-1)>>1; if(d[heap[q]]<=k)break; heap[p]=heap[q]; hpos[heap[p]]=p; p=q;} heap[p]=e; hpos[e]=p; }
static void hdown(int p){ int e=heap[p]; double k=d[e]; for(;;){int c=2*p+1; if(c>=hn)break; if(c+1<hn && d[heap[c+1]]<d[heap[c]])c++; if(d[heap[c]]>=k)break; heap[p]=heap[c]; hpos[heap[p]]=p; p=c;} heap[p]=e; hpos[e]=p; }
static void hpush(int j){ heap[hn]=j; hpos[j]=hn; hn++; hup(hn-1); }
static int hpop(){ int r=heap[0]; hn--; if(hn>0){heap[0]=heap[hn]; hpos[heap[0]]=0; hdown(0);} hpos[r]=-1; return r; }
static void addedge(int n,int i,int j){ int *a=adj+(size_t)i*n; for(int k=0;k<deg[i];k++) if(a[k]==j) return; a[deg[i]++]=j; }

/* returns 0 ok, -1 failure (no path) */
static int augment(int n, const double *C, int *x, int s){
  int ns=0; hn=0;
  const double *r=C+(size_t)s*n; int *a=adj+(size_t)s*n;
  for(int k=0;k<deg[s];k++){int j=a[k]; double h=r[j]-u[s]-v[j]; if(hpos[j]==-2){d[j]=h;pred[j]=s;hpush(j);} else if(h<d[j]){d[j]=h;pred[j]=s;hup(hpos[j]);} }
  int end=-1; double D=0;
  while(hn>0){
    int j=hpop(); fin[j]=1; scan[ns++]=j; double dj=d[j];
    if(y[j]<0){end=j;D=dj;break;}
    int i=y[j]; const double *ri=C+(size_t)i*n; int *ai=adj+(size_t)i*n; double base=dj-u[i];
    for(int k=0;k<deg[i];k++){int c=ai[k]; if(fin[c])continue; double h=base+ri[c]-v[c];
      if(hpos[c]==-2){d[c]=h;pred[c]=i;hpush(c);} else if(h<d[c]){d[c]=h;pred[c]=i;hup(hpos[c]);} }
  }
  /* reset heap leftovers */
  for(int k=0;k<hn;k++) hpos[heap[k]]=-2;
  for(int k=0;k<ns;k++){ hpos[scan[k]]=-2; fin[scan[k]]=0; }
  if(end<0) return -1;
  for(int k=0;k<ns;k++){int j=scan[k]; v[j]+=d[j]-D;}
  int j=end;
  for(;;){int i=pred[j]; y[j]=i; int t=x[i]; x[i]=j; if(i==s)break; j=t;}
  /* update u of rows on scanned set */
  for(int k=0;k<ns;k++){int j=scan[k]; int i=y[j]; if(i>=0) u[i]=C[(size_t)i*n+j]-v[j];}
  return 0;
}

int sparse_lap(int n, const double *C, int *x, int K, int KC){
  ensure(n);
  if(K>n)K=n; if(KC>n)KC=n;
  /* row top-K */
  double bk[64]; int bj[64];
  double *cb=malloc(sizeof(double)*n*KC); int *ci=malloc(sizeof(int)*n*KC); double *cthr=malloc(sizeof(double)*n); int *cn=calloc(n,sizeof(int));
  for(int j=0;j<n;j++) cthr[j]=INF;
  for(int i=0;i<n;i++){
    const double *r=C+(size_t)i*n; int m=0; double thr=INF;
    for(int j=0;j<n;j++){
      double c=r[j];
      if(c<thr){ int p=m<K?m++:K-1; while(p>0&&bk[p-1]>c){bk[p]=bk[p-1];bj[p]=bj[p-1];p--;} bk[p]=c;bj[p]=j; if(m==K)thr=bk[K-1]; }
      if(c<cthr[j]){ double *b=cb+(size_t)j*KC; int *bi=ci+(size_t)j*KC; int p=cn[j]<KC?cn[j]++:KC-1; while(p>0&&b[p-1]>c){b[p]=b[p-1];bi[p]=bi[p-1];p--;} b[p]=c;bi[p]=i; if(cn[j]==KC)cthr[j]=b[KC-1]; }
    }
    int *a=adj+(size_t)i*n; for(int k=0;k<m;k++)a[k]=bj[k]; deg[i]=m;
    u[i]=bk[0];
  }
  for(int j=0;j<n;j++) for(int k=0;k<cn[j];k++) addedge(n,ci[(size_t)j*KC+k],j);
  free(cb);free(ci);free(cthr);free(cn);
  for(int j=0;j<n;j++){v[j]=0;y[j]=-1;fin[j]=0;hpos[j]=-2;}
  for(int i=0;i<n;i++) x[i]=-1;
  int nf=0; int *fr=malloc(sizeof(int)*n);
  for(int i=0;i<n;i++){ int j=adj[(size_t)i*n]; if(y[j]<0){y[j]=i;x[i]=j;} else fr[nf++]=i; }
  int rounds=0;
  for(;;){
    for(int f=0;f<nf;f++) if(augment(n,C,x,fr[f])<0){ free(fr); return lapjv(n,C,x); }
    /* verify duals on full matrix */
    nf=0;
    for(int i=0;i<n;i++){
      const double *r=C+(size_t)i*n; double ui=u[i]; double mn=INF;
      for(int j=0;j<n;j++){double h=r[j]-v[j]; mn=h<mn?h:mn;}
      if(mn<ui-1e-13){
        for(int j=0;j<n;j++) if(r[j]-v[j]<ui-1e-13) addedge(n,i,j);
        u[i]=mn; y[x[i]]=-1; x[i]=-1; fr[nf++]=i;
      }
    }
    if(nf==0) break;
    if(++rounds>50){ free(fr); return lapjv(n,C,x); }
  }
  free(fr);
  return rounds;
}
